# ============================================================================
# THE HUMANS ARE FINE - build every discovery artifact in the right order
#
# This is the single command that must run before a publish. It exists because
# a news sitemap that is regenerated by hand will be stale the first time
# someone publishes in a hurry, and a stale news sitemap is worse than none:
# Google reads it as the current list of recent articles.
#
# Order matters:
#   1. page dates   - git-derived; the sitemap refuses to run without it
#   2. sitemap.xml  - all tracked pages
#   3. social cards - one per article, from the article's own h1 and date
#   4. news-sitemap - only articles inside the 48 hour window
#   5. verify       - asserts the artifacts agree with the pages
#
# Nothing here deploys. It writes files into the working tree, and the commit
# is still a separate, deliberate act.
# ============================================================================
param(
    [switch]$SkipDates
)
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
Push-Location $repo
try {
    $steps = [ordered]@{
        'page dates'   = { powershell -NoProfile -ExecutionPolicy Bypass -File 'scripts\thaf-page-dates.ps1' }
        'sitemap.xml'  = { powershell -NoProfile -ExecutionPolicy Bypass -File 'scripts\thaf-build-sitemap.ps1' }
        'social cards' = { powershell -NoProfile -ExecutionPolicy Bypass -File 'scripts\thaf-build-social-cards.ps1' }
        'news sitemap' = { powershell -NoProfile -ExecutionPolicy Bypass -File 'scripts\thaf-build-news-sitemap.ps1' }
    }
    foreach ($name in $steps.Keys) {
        if ($name -eq 'page dates' -and $SkipDates) {
            Write-Output ("-- {0} (skipped)" -f $name)
            continue
        }
        Write-Output ("-- {0}" -f $name)
        & $steps[$name]
        if ($LASTEXITCODE -ne 0) { throw "step failed: $name (exit $LASTEXITCODE)" }
    }

    Write-Output '-- verify'
    & powershell -NoProfile -ExecutionPolicy Bypass -File 'scripts\thaf-verify-discovery.ps1'
    if ($LASTEXITCODE -ne 0) { throw 'discovery verification failed - do not publish this tree' }

    Write-Output ''
    Write-Output 'discovery build OK'
}
finally { Pop-Location }
